<script>(function(){
  setTimeout(function(){

    try{
      var btns=document.querySelectorAll('.yw-btn');for(var bi=1;bi<btns.length;bi++)btns[bi].remove();
      var modals=document.querySelectorAll('#yw-modal');for(var mi=1;mi<modals.length;mi++)modals[mi].remove();
      var bgl=document.querySelectorAll('#yw-bg-layer');for(var li=1;li<bgl.length;li++)bgl[li].remove();
    }catch(e){}
  },0);
  if(window.__ywAssistantActive){

    return;
  }
  window.__ywAssistantActive=true;
  function _ywApplyBtnSkin(skin){
    var btn=document.getElementById('yw-side-btn');
    if(!btn)return;
    var breathing=btn.classList.contains('breathing');
    btn.className='yw-btn '+(skin||'yw-sakura')+(breathing?' breathing':'');
  }
  function _ywApplyThemeAll(cls){
    var m=document.getElementById('yw-modal');
    if(m)m.className=cls;
    var skin=(cls||'').split(' ')[1]||'yw-sakura';
    _ywApplyBtnSkin(skin);
  }
  window.ywOpen=function(){
    event.stopPropagation();
    var m=document.getElementById('yw-modal'),box=m.querySelector('.yw-box'),btn=document.getElementById('yw-side-btn');
    try{var t=localStorage.getItem('yw_theme');if(t){_ywApplyThemeAll(t);if(t.indexOf('yw-custom')>-1){var ct=localStorage.getItem('yw_customtheme');if(ct&&typeof _ywApplyCustomThemeCSS==='function')_ywApplyCustomThemeCSS(ct);}}}catch(e){}
    m.style.display='flex';
    _ywBeep(880,.08);
    _ywStatsOpens++;try{_ywSaveStats();}catch(e){}
    if(typeof _ywMaybeGreet==='function')_ywMaybeGreet();
    if(typeof _ywBindWordCount==='function'){_ywBindWordCount();_ywRefreshWordCount();}
    if(box&&btn){
      requestAnimationFrame(function(){
        var r=btn.getBoundingClientRect(),br=box.getBoundingClientRect();
        var ox=(r.left+r.width/2)-br.left,oy=(r.top+r.height/2)-br.top;
        box.style.transformOrigin=ox+'px '+oy+'px';
        box.style.transition='none';box.style.transform='scale(.12)';box.style.opacity='0';
        requestAnimationFrame(function(){
          box.style.transition='transform .46s cubic-bezier(.34,1.4,.64,1),opacity .32s ease';
          box.style.transform='scale(1)';box.style.opacity='1';
          setTimeout(function(){box.style.transition='';box.style.transform='';},480);
        });
      });
    }
  };
  function _ywCloseModalCore(){
    var m=document.getElementById('yw-modal'),box=m.querySelector('.yw-box');
    if(box){
      box.style.transition='transform .26s cubic-bezier(.4,0,.2,1),opacity .24s ease';
      box.style.transform='scale(.86)';box.style.opacity='0';
      setTimeout(function(){m.style.display='none';box.style.transition='';box.style.transform='';box.style.opacity='';},250);
    }else{m.style.display='none';}
  }
  window.ywClose=function(){event.stopPropagation();_ywCloseModalCore();};
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){
      var m=document.getElementById('yw-modal');
      if(m&&getComputedStyle(m).display!=='none')_ywCloseModalCore();
    }
  });
  var _ywCur=0;
  window.ywTab=function(idx){
    if(idx===_ywCur)return;
    _ywBeep(760,.05);
    var panels=document.querySelectorAll('#yw-modal .yw-content');
    var tabs=document.querySelectorAll('#yw-modal .yw-tab');
    var dir=idx>_ywCur?1:-1;
    var outP=panels[_ywCur],inP=panels[idx];
    outP.style.transition='transform .3s cubic-bezier(.4,0,.2,1)';
    outP.style.transform='translateX('+(dir<0?105:-105)+'%)';
    inP.style.transition='none';
    inP.style.transform='translateX('+(dir>0?105:-105)+'%)';
    inP.classList.add('yw-active');
    inP.offsetWidth;
    inP.style.transition='transform .3s cubic-bezier(.4,0,.2,1)';

inP.style.transform='translateX(0)';
    setTimeout(function(){outP.classList.remove('yw-active');outP.style.transition='';outP.style.transform='translateX('+(dir<0?105:-105)+'%)';},320);
    tabs.forEach(function(t,i){t.classList.toggle('yw-tab-active',i===idx);});
    _ywCur=idx;
    if(idx===3&&typeof _ywRenderOverview==='function')_ywRenderOverview();
