function _ywBeep(freq,dur){
  if(!_ywSoundOn)return;
  try{
    if(!_ywAudioCtx)_ywAudioCtx=new (window.AudioContext||window.webkitAudioContext)();
    var ctx=_ywAudioCtx;if(ctx.state==='suspended')ctx.resume();
    var o=ctx.createOscillator(),g=ctx.createGain();
    o.type='sine';o.frequency.value=freq||880;
    g.gain.value=0.0001;
    o.connect(g);g.connect(ctx.destination);
    var now=ctx.currentTime,d=dur||0.12;
    g.gain.exponentialRampToValueAtTime(0.07,now+0.012);
    g.gain.exponentialRampToValueAtTime(0.0001,now+d);
    o.start(now);o.stop(now+d+0.02);
  }catch(e){}
}
