function _ywActiveLyricIdx(lines,t){
  var idx=-1;
  for(var i=0;i<lines.length;i++){if(lines[i].time<=t)idx=i;else break;}
  return idx;
}
function _ywUpdateCountdownBadge(show,text){
  var el=document.getElementById('yw-lyrics-countdown');
  if(!show){if(el)el.style.opacity='0';return;}
  if(!el){
    el=document.createElement('div');el.id='yw-lyrics-countdown';
    el.style.cssText='position:fixed;right:10px;bottom:14px;z-index:99989;padding:5px 12px;border-radius:20px;font-size:10px;font-family:"ZCOOL QingKe HuangYou",serif;letter-spacing:1px;color:#fff;background:rgba(40,10,30,.6);box-shadow:0 2px 10px rgba(0,0,0,.3);opacity:0;transition:opacity .3s ease;pointer-events:none;';
    document.body.appendChild(el);
  }
  el.textContent=text;el.style.opacity='.88';
}
function _ywTxtTick(){
  if(!_ywTxtOn)return;
  var M=window._ym;
  var ci=M?M.ci:-1;
  var curSongName=(M&&ci>=0&&M.songs[ci])?M.songs[ci].name:'';
  var lines=curSongName?_ywLyricsMap[curSongName]:null;
  if(lines&&lines.length){
    var t=(M.au?M.au.currentTime:0);
    var idx=_ywActiveLyricIdx(lines,t);
    if(idx<0){
      if(_ywTxtCurKey!==null){_ywFadeOutFloat();_ywTxtCurKey=null;}
      _ywUpdateCountdownBadge(true,'下一句 '+_ywFmtTime(Math.max(0,lines[0].time-t))+' 后');
      return;
    }
    var key='lyric:'+curSongName+':'+idx;
    if(key!==_ywTxtCurKey){_ywTxtCurKey=key;_ywRenderFloat(lines[idx].text);}
    if(idx+1<lines.length)_ywUpdateCountdownBadge(true,'下一句 '+_ywFmtTime(Math.max(0,lines[idx+1].time-t))+' 后');
    else _ywUpdateCountdownBadge(false);
  }else{
    _ywUpdateCountdownBadge(false);
    var now=Date.now();
    var content=curSongName||'游玩助手';
    var key2='title:'+content;
    if(now>=_ywTxtLoopAt||key2!==_ywTxtCurKey){
      _ywTxtCurKey=key2;_ywRenderFloat(content);
      _ywTxtLoopAt=now+3600+content.length*60;
    }
  }
}
function _ywFadeOutFloat(){
  if(_ywTxtCurEl){
    var old=_ywTxtCurEl;
    old.style.transition='opacity .3s';old.style.opacity='0';
    setTimeout(function(){if(old.parentNode)old.remove();},320);
    _ywTxtCurEl=null;
  }
}
function _ywCharColorCSS(){
  if(_ywColorMode==='black')return 'color:#111;';
  if(_ywColorMode==='white')return 'color:#fff;';

  if(_ywColorMode==='custom')return 'color:'+_ywColorCustom+';';
  return '';
}
function _ywRenderFloat(title){
  _ywFadeOutFloat();
  var chars=title.split('');
  var fs=30,cw=fs*1.25;
  var totalW=chars.length*cw+chars.length*4;
  var maxX=Math.max(window.innerWidth-totalW-20,20);
  var maxY=Math.max(window.innerHeight-fs*4,fs);
  var x=Math.random()*maxX;
  var y=Math.random()*maxY+fs;
  var el=document.createElement('div');
  el.style.cssText='position:fixed;z-index:99991;pointer-events:none;left:'+x+'px;top:'+y+'px;display:flex;gap:4px;flex-wrap:nowrap;';
  document.body.appendChild(el);
  _ywTxtCurEl=el;
  var fixedColor=(_ywColorMode!=='sweep');
  var colorCSS=_ywCharColorCSS();
  var fontFam=_ywFontFamily||'ZCOOL QingKe HuangYou';
  var delay=0;
  chars.forEach(function(ch){
    setTimeout(function(){
      if(_ywTxtCurEl!==el)return;
      var sp=document.createElement('span');
      sp.textContent=ch;
      var floatDur=(1.4+Math.random()*0.8).toFixed(2);
      var floatDel=(Math.random()*0.8).toFixed(2);
      var anim='yw-charfloat '+floatDur+'s ease-in-out '+floatDel+'s infinite';
      if(!fixedColor){
        var colorDur=(1.8+Math.random()*1.5).toFixed(2);
        var colorDel=(Math.random()*1.5).toFixed(2);
        anim+=',yw-colorsweep '+colorDur+'s linear '+colorDel+'s infinite';
      }
      var shadow=fixedColor?'0 1px 2px rgba(0,0,0,.55),0 0 3px rgba(255,255,255,.55)':'0 0 14px currentColor';
      sp.style.cssText='font-size:'+fs+'px;font-weight:bold;font-family:"'+fontFam+'",cursive,serif;display:inline-block;opacity:0;transition:opacity .3s cubic-bezier(.4,0,.2,1);animation:'+anim+';'+colorCSS+'text-shadow:'+shadow+';will-change:transform,opacity;';
      el.appendChild(sp);
      setTimeout(function(){if(sp.parentNode)sp.style.opacity='1';},30);
    },delay);
    delay+=180;
  });
}

