function _ywFmtTime(sec){sec=Math.max(0,Math.round(sec));var m=Math.floor(sec/60),s=sec%60;return m+':'+(s<10?'0':'')+s;}
function _ywParseTime(str){
  str=(str||'').trim();if(!str)return 0;
  if(str.indexOf(':')>-1){var p=str.split(':');return (parseFloat(p[0])||0)*60+(parseFloat(p[1])||0);}
  return parseFloat(str)||0;
}
