window.ywHandleImportFile=function(inputEl){
  event.stopPropagation();
  var file=inputEl.files&&inputEl.files[0];
  if(!file)return;
  var reader=new FileReader();
  reader.onload=function(){
    var data;
    try{data=JSON.parse(reader.result);}catch(e){_ywToast('✕ 不是有效的设置文件',true);inputEl.value='';return;}
    if(!data||typeof data!=='object'){_ywToast('✕ 文件内容无效',true);inputEl.value='';return;}
    if(!window.confirm('导入将覆盖当前的歌曲列表、图片列表、歌词、指令库与颜色等设置，确定继续吗？')){inputEl.value='';return;}
    if(typeof data.theme==='string'&&data.theme){
      try{_ywApplyThemeAll(data.theme);localStorage.setItem('yw_theme',data.theme);}catch(e){}
    }
    if(typeof data.customTheme==='string'&&data.customTheme){
      try{localStorage.setItem('yw_customtheme',data.customTheme);}catch(e){}
      _ywApplyCustomThemeCSS(data.customTheme);
    }
    if(typeof data.bg==='string'){
      try{
        var ly=document.getElementById('yw-bg-layer');
        if(data.bg){if(ly){ly.style.backgroundImage='url('+data.bg+')';ly.style.backgroundSize='cover';ly.style.backgroundPosition='center';}localStorage.setItem('yw_bg',data.bg);}
        else{if(ly)ly.style.backgroundImage='';localStorage.removeItem('yw_bg');}
