      if(data.rest){
        _ywRestOn=!!data.rest.on;_ywRestMinutes=data.rest.min||30;_ywSaveRest();
        var rc=document.getElementById('yw-rest-toggle');if(rc)rc.checked=_ywRestOn;
        var rs=document.getElementById('yw-rest-minutes');if(rs)rs.value=String(_ywRestMinutes);
