      if(data.autoInject&&typeof data.autoInject==='object'){
        var ai=data.autoInject;
        _ywAutoInjOn=!!ai.on;_ywInjActiveIdx=ai.activeIdx||0;_ywInjDelay=ai.delay||90;_ywInjRandomMode=!!ai.random;
        if(Array.isArray(ai.schemes)&&ai.schemes.length)_ywInjSchemes=ai.schemes;
        if(Array.isArray(ai.inputSel)&&ai.inputSel.length)_ywInjInputSel=ai.inputSel;
        if(Array.isArray(ai.sendSel)&&ai.sendSel.length)_ywInjSendSel=ai.sendSel;
        _ywInjEnsureSchemes();_ywSaveInjSettings();
        try{localStorage.setItem('yw_inj_random',_ywInjRandomMode?'1':'0');}catch(e){}
        var it=document.getElementById('yw-autoinj-toggle');if(it)it.checked=_ywAutoInjOn;
        var rmcb=document.getElementById('yw-inj-random-toggle');if(rmcb)rmcb.checked=_ywInjRandomMode;
        _ywRenderSchemeGrid();_ywRenderSchemeEditor();_ywRenderInjSelLists();
        _ywPanelSync(document.getElementById('yw-inj-settings-panel'));
      }
      if(Array.isArray(data.favSongs)){
        _ywFavSongs=data.favSongs;try{_ywSaveFavSongs();}catch(e){}
        if(window._ym)window._ym.rebuildList();
      }
      if(typeof data.greet==='boolean'){
        _ywGreetOn=data.greet;try{localStorage.setItem('yw_greet',_ywGreetOn?'1':'0');}catch(e){}
        var grcb=document.getElementById('yw-greet-toggle');if(grcb)grcb.checked=_ywGreetOn;
      }
      if(Array.isArray(data.wpFolders)){
        _ywWpFolders=data.wpFolders;_ywWpOpenIdx={};
        try{_ywWpSave();}catch(e){}
        if(typeof _ywWpRender==='function')_ywWpRender();
      }
      _ywRenderOverview();
      _ywToast('✓ 导入成功，已恢复全部设置');
      inputEl.value='';
    };
    reader.onerror=function(){_ywToast('✕ 读取文件失败',true);inputEl.value='';};
    reader.readAsText(file);
  };


  var _ywAutoInjOn=false;
  var _ywInjActiveIdx=0;
  var _ywInjDelay=90;
  var _ywInjSchemes=null;
  var _ywInjDefaultInputSel=['.uni-textarea-textarea','[contenteditable="true"]','textarea','input[type="text"]'];
  var _ywInjDefaultSendSel=['.send-btn','.btn-send','.icon-send','[class*="send" i]','button[type="submit"]'];
  var _ywInjInputSel=_ywInjDefaultInputSel.slice();
  var _ywInjSendSel=_ywInjDefaultSendSel.slice();
  var _ywInjProgFlag=false,_ywInjBusy=false,_ywInjFailCount=0,_ywInjRandomMode=false;

  function _ywInjEnsureSchemes(){
    if(_ywInjSchemes&&_ywInjSchemes.length===10)return _ywInjSchemes;
    var old=_ywInjSchemes||[];
    var arr=[];
    for(var i=0;i<10;i++){arr.push(old[i]||{name:'方案'+(i+1),text:'',pos:'end'});}
    _ywInjSchemes=arr;
    return _ywInjSchemes;
  }
  function _ywPickScheme(){
    var schemes=_ywInjEnsureSchemes();
    if(_ywInjRandomMode){
      var filled=[];
      for(var i=0;i<schemes.length;i++){if(schemes[i].text)filled.push(i);}
      if(!filled.length)return {scheme:null,idx:-1};
      var pick=filled[Math.floor(Math.random()*filled.length)];
      return {scheme:schemes[pick],idx:pick};
    }
    return {scheme:schemes[_ywInjActiveIdx],idx:_ywInjActiveIdx};
  }
  window.ywToggleInjRandom=function(cb){
    event.stopPropagation();_ywInjRandomMode=cb.checked;
    try{localStorage.setItem('yw_inj_random',_ywInjRandomMode?'1':'0');}catch(e){}
    _ywToast(_ywInjRandomMode?'🎲 随机模式已开启':'已切换回固定方案');
  };
  function _ywIsUsableInput(el){
    if(!el)return false;
    if(el.disabled||el.readOnly)return false;
    var cs;try{cs=getComputedStyle(el);}catch(e){return false;}
    if(!cs||cs.display==='none'||cs.visibility==='hidden')return false;
    if(!(el.offsetWidth>0&&el.offsetHeight>0))return false;
    var tag=(el.tagName||'').toLowerCase();
    var ce=el.getAttribute&&el.getAttribute('contenteditable');
    if(tag!=='textarea'&&tag!=='input'&&ce!=='true'&&ce!=='')return false;
    return true;
  }
  function _ywFindVisibleInput(scopeEl){
    var root=scopeEl||document;
    for(var i=0;i<_ywInjInputSel.length;i++){
      var els;try{els=root.querySelectorAll(_ywInjInputSel[i]);}catch(e){continue;}
      for(var j=0;j<els.length;j++){if(_ywIsUsableInput(els[j]))return els[j];}
    }
    return null;
  }
  function _ywFindNearbyInput(btn){

    var node=btn,depth=0;
    while(node&&node.nodeType===1&&depth<5){
      var found=_ywFindVisibleInput(node);
      if(found)return found;
      node=node.parentElement;depth++;
    }
    return _ywFindVisibleInput(document);
  }
  function _ywFindSendButton(triggerEl){
    var node=triggerEl,depth=0;
    while(node&&node.nodeType===1&&depth<6){
      for(var i=0;i<_ywInjSendSel.length;i++){
        try{if(node.matches&&node.matches(_ywInjSendSel[i]))return node;}catch(e){}
      }
      node=node.parentElement;depth++;
    }
    return null;
  }
  function _ywFindSendButtonGlobal(){

    for(var i=0;i<_ywInjSendSel.length;i++){
      var els;try{els=document.querySelectorAll(_ywInjSendSel[i]);}catch(e){continue;}
      for(var j=0;j<els.length;j++){if(els[j].offsetWidth>0&&els[j].offsetHeight>0)return els[j];}
    }
    return null;
  }
  function _ywNativeSetValue(el,value){
    try{
      var proto=el.tagName.toLowerCase()==='textarea'?window.HTMLTextAreaElement.prototype:window.HTMLInputElement.prototype;
      var desc=Object.getOwnPropertyDescriptor(proto,'value');
      if(desc&&desc.set){desc.set.call(el,value);return;}
    }catch(e){}
    el.value=value;
  }
  function _ywWriteInjectValue(el,text,pos){
    if(!el||!text)return;
    var isCE=el.getAttribute&&(el.getAttribute('contenteditable')==='true'||el.getAttribute('contenteditable')==='');
    if(isCE){
      var cur=el.textContent||'';
      el.textContent=pos==='start'?(text+cur):(cur+text);
    }else{
      var cur=el.value||'';
      _ywNativeSetValue(el,pos==='start'?(text+cur):(cur+text));
    }
    ['input','change','keyup'].forEach(function(t){try{el.dispatchEvent(new Event(t,{bubbles:true}));}catch(e){}});
    try{
      var wrapper=el.closest&&(el.closest('.uni-textarea-wrapper')||el.closest('.uni-input-wrapper'));
      if(wrapper){
        var ph=wrapper.querySelector('.uni-textarea-placeholder,.uni-input-placeholder');
        if(ph)ph.style.display=(el.value||el.textContent||'').length>0?'none':'';
      }
    }catch(e){}
  }
  function _ywInjectOnSendHandler(e){
    if(!_ywAutoInjOn)return;
    if(_ywInjProgFlag)return;
    var btn=_ywFindSendButton(e.target);
    if(!btn)return;
    try{e.preventDefault();e.stopPropagation();if(e.stopImmediatePropagation)e.stopImmediatePropagation();}catch(err){}
    if(_ywInjBusy)return;
    _ywInjBusy=true;
    function doResend(){
      _ywInjProgFlag=true;
      try{btn.click();}catch(err){}
      setTimeout(function(){_ywInjProgFlag=false;_ywInjBusy=false;},60);
    }
    var picked=_ywPickScheme();
    var scheme=picked.scheme;
    if(!scheme||!scheme.text){setTimeout(doResend,0);return;}
    var input=_ywFindNearbyInput(btn);
    if(input){
      _ywWriteInjectValue(input,scheme.text,scheme.pos||'end');
      _ywInjFailCount=0;
      if(_ywInjRandomMode)_ywToast('🎲 这次抽到了：'+(scheme.name||('方案'+(picked.idx+1))));
    }else{
      _ywInjFailCount++;
      if(_ywInjFailCount>=3){
        _ywAutoInjOn=false;_ywInjFailCount=0;
        try{_ywSaveInjSettings();}catch(err){}
        var cb=document.getElementById('yw-autoinj-toggle');if(cb)cb.checked=false;
        _ywToast('⚠️ 自动注入连续3次没找到输入框，已自动关闭，请检查"输入框选择器"设置',true);
      }
    }
    setTimeout(doResend,_ywInjDelay);
  }
  function _ywBindAutoInject(){
    if(window._ywInjBound)return;
    window._ywInjBound=true;
    ['pointerdown','mousedown','touchend','click'].forEach(function(t){
      document.addEventListener(t,_ywInjectOnSendHandler,true);
    });
  }
  function _ywSaveInjSettings(){
    try{localStorage.setItem('yw_autoinj',JSON.stringify({
      on:_ywAutoInjOn,activeIdx:_ywInjActiveIdx,delay:_ywInjDelay,
      schemes:_ywInjEnsureSchemes(),inputSel:_ywInjInputSel,sendSel:_ywInjSendSel
    }));}catch(e){}
  }
  window.ywToggleAutoInject=function(cb){
    event.stopPropagation();_ywAutoInjOn=cb.checked;_ywSaveInjSettings();
    _ywToast(_ywAutoInjOn?'🚀 自动注入已开启':'已关闭自动注入');
  };
  function _ywRenderSchemeGrid(){
    var grid=document.getElementById('yw-scheme-grid');if(!grid)return;
    var schemes=_ywInjEnsureSchemes();
    grid.innerHTML='';
    schemes.forEach(function(s,i){
      var b=document.createElement('div');
      b.className='yw-scheme-btn'+(i===_ywInjActiveIdx?' active':'')+(s.text?' filled':'');
      b.textContent=(i+1);
      b.title=s.name||('方案'+(i+1));
      b.onclick=function(ev){ev.stopPropagation();ywSchemeSwitch(i);};
      grid.appendChild(b);
    });
  }
  window.ywSchemeSwitch=function(idx){
    _ywInjActiveIdx=idx;_ywSaveInjSettings();
    _ywRenderSchemeGrid();_ywRenderSchemeEditor();
    _ywBeep(820,.07);
    var s=_ywInjEnsureSchemes()[idx];
    _ywToast('已切换到「'+(s.name||('方案'+(idx+1)))+'」');
  };
  function _ywRenderSchemeEditor(){
    var s=_ywInjEnsureSchemes()[_ywInjActiveIdx];
    var ne=document.getElementById('yw-scheme-name-in'),te=document.getElementById('yw-scheme-text-in');
    if(ne)ne.value=s.name||'';
    if(te)te.value=s.text||'';
    document.querySelectorAll('.yw-pos-opt').forEach(function(el){el.classList.toggle('active',el.dataset.pos===(s.pos||'end'));});
  }
  var _ywSaveInjSettingsDebounced=_ywDebounce(_ywSaveInjSettings,400);
  window.ywSchemeNameInput=function(inp){
    var s=_ywInjEnsureSchemes()[_ywInjActiveIdx];s.name=inp.value;
    _ywSaveInjSettingsDebounced();
    var grid=document.getElementById('yw-scheme-grid');
    if(grid&&grid.children[_ywInjActiveIdx])grid.children[_ywInjActiveIdx].title=inp.value||('方案'+(_ywInjActiveIdx+1));
  };
  window.ywSchemeTextInput=function(ta){
    var s=_ywInjEnsureSchemes()[_ywInjActiveIdx];s.text=ta.value;
    _ywSaveInjSettingsDebounced();
    var grid=document.getElementById('yw-scheme-grid');
    if(grid&&grid.children[_ywInjActiveIdx])grid.children[_ywInjActiveIdx].classList.toggle('filled',!!ta.value);
  };
  window.ywSchemePosSet=function(pos){
    event.stopPropagation();
    var s=_ywInjEnsureSchemes()[_ywInjActiveIdx];s.pos=pos;_ywSaveInjSettings();
    document.querySelectorAll('.yw-pos-opt').forEach(function(el){el.classList.toggle('active',el.dataset.pos===pos);});
  };
  window.ywToggleInjSettings=function(){
    event.stopPropagation();
    var p=document.getElementById('yw-inj-settings-panel');
    _ywPanelToggle(p,function(){_ywRenderInjSelLists();},document.querySelector('[data-gear=inj]'));
  };
  function _ywRenderInjSelLists(){
    _ywRenderSelList('yw-inj-inputsel-items',_ywInjInputSel,_ywInjInputSelMove,_ywInjInputSelDel);
    _ywRenderSelList('yw-inj-sendsel-items',_ywInjSendSel,_ywInjSendSelMove,_ywInjSendSelDel);
    var ds=document.getElementById('yw-inj-delay-slider'),dl=document.getElementById('yw-inj-delay-label');
    if(ds)ds.value=_ywInjDelay;if(dl)dl.textContent=_ywInjDelay+'ms';
  }
  function _ywRenderSelList(wrapId,list,moveFn,delFn){
    var wrap=document.getElementById(wrapId);if(!wrap)return;
    wrap.innerHTML='';
    if(!list.length){wrap.innerHTML='<div class="yw-imglist-empty">暂无选择器</div>';return;}
    list.forEach(function(sel,i){
      var row=document.createElement('div');row.className='yw-imglist-row';
      row.innerHTML='<span class="yw-imglist-idx">'+(i+1)+'</span>'+
        '<span class="yw-imglist-url" title="'+String(sel).replace(/"/g,'&quot;')+'">'+sel+'</span>'+
        '<div class="yw-imglist-btns"><span data-act="up">⬆</span><span data-act="down">⬇</span><span data-act="del">✕</span></div>';
      row.querySelector('[data-act=up]').onclick=function(e){e.stopPropagation();moveFn(i,-1);};
      row.querySelector('[data-act=down]').onclick=function(e){e.stopPropagation();moveFn(i,1);};
      row.querySelector('[data-act=del]').onclick=function(e){e.stopPropagation();delFn(i);};
      wrap.appendChild(row);
    });
  }
  function _ywInjInputSelMove(i,dir){var j=i+dir;if(j<0||j>=_ywInjInputSel.length)return;var t=_ywInjInputSel[i];_ywInjInputSel[i]=_ywInjInputSel[j];_ywInjInputSel[j]=t;_ywSaveInjSettings();_ywRenderInjSelLists();_ywPanelSync(document.getElementById('yw-inj-settings-panel'));}
  function _ywInjInputSelDel(i){_ywInjInputSel.splice(i,1);_ywSaveInjSettings();_ywRenderInjSelLists();_ywPanelSync(document.getElementById('yw-inj-settings-panel'));}
  function _ywInjSendSelMove(i,dir){var j=i+dir;if(j<0||j>=_ywInjSendSel.length)return;var t=_ywInjSendSel[i];_ywInjSendSel[i]=_ywInjSendSel[j];_ywInjSendSel[j]=t;_ywSaveInjSettings();_ywRenderInjSelLists();_ywPanelSync(document.getElementById('yw-inj-settings-panel'));}
  function _ywInjSendSelDel(i){_ywInjSendSel.splice(i,1);_ywSaveInjSettings();_ywRenderInjSelLists();_ywPanelSync(document.getElementById('yw-inj-settings-panel'));}
  window.ywInjAddInputSel=function(){
    event.stopPropagation();
    var inp=document.getElementById('yw-inj-inputsel-in');var v=inp&&inp.value.trim();if(!v)return;
    _ywInjInputSel.push(v);if(inp)inp.value='';
    _ywSaveInjSettings();_ywRenderInjSelLists();_ywPanelSync(document.getElementById('yw-inj-settings-panel'));
  };
  window.ywInjAddSendSel=function(){
    event.stopPropagation();
    var inp=document.getElementById('yw-inj-sendsel-in');var v=inp&&inp.value.trim();if(!v)return;
    _ywInjSendSel.push(v);if(inp)inp.value='';
    _ywSaveInjSettings();_ywRenderInjSelLists();_ywPanelSync(document.getElementById('yw-inj-settings-panel'));
  };
  window.ywInjResetSelectors=function(){
    event.stopPropagation();
    _ywInjInputSel=_ywInjDefaultInputSel.slice();_ywInjSendSel=_ywInjDefaultSendSel.slice();
    _ywSaveInjSettings();_ywRenderInjSelLists();_ywPanelSync(document.getElementById('yw-inj-settings-panel'));
    _ywToast('已恢复默认选择器');
  };
  window.ywSetInjDelay=function(inp){
    event.stopPropagation();_ywInjDelay=parseInt(inp.value)||90;
    var dl=document.getElementById('yw-inj-delay-label');if(dl)dl.textContent=_ywInjDelay+'ms';
    _ywSaveInjSettings();
  };
  window.ywInjTestMatch=function(){
    event.stopPropagation();
    var input=_ywFindVisibleInput();
    var btn=_ywFindSendButtonGlobal();
    var msg='输入框：'+(input?('✓ 已找到 <'+input.tagName.toLowerCase()+'>'):'✕ 未找到')+
      '　发送按钮：'+(btn?('✓ 已找到 <'+btn.tagName.toLowerCase()+'>'):'✕ 未找到（可手动点一下发送按钮再试，或检查选择器）');
    _ywToast(msg,!(input&&btn));
  };
})();</script>

